namespace SysAdminAssistant.Core;
public static class LinuxIssueAdvice
{
    public static string? Describe(AgentFinding finding,AgentReport r,AgentPolicy p,bool compact=false)
    {
        if(!r.Os.StartsWith("Linux ",StringComparison.OrdinalIgnoreCase))return null;
        var key=finding.Key;
        if(key=="swap")return global::SysAdminAssistant.Core.ProductText.Get($"Хост {r.MachineName}; проверено {r.CapturedUtc.ToServerTime():dd.MM.yyyy HH:mm:ss}. Swap занят {AgentIssueAdvice.Size(r.SwapTotalBytes-r.SwapFreeBytes)} из {AgentIssueAdvice.Size(r.SwapTotalBytes)}; свободно {AgentIssueAdvice.Size(r.SwapFreeBytes)}; порог ≥ {p.Linux?.SwapUsedPercent}%. Доступно RAM {AgentIssueAdvice.Size(r.MemoryAvailableBytes)}.\nЧто проверить: free -h, vmstat 1 5, процессы по памяти и ограничения ВМ/контейнера. Занятый swap без активного обмена сам по себе не доказывает нехватку RAM. Не выключай swap на работающем сервере вслепую.\nЗакрытие: свежий отчёт ниже порога; задержка тревоги ")+finding.DelayMinutes+global::SysAdminAssistant.Core.ProductText.Get(" мин.");
        if(key.StartsWith("disk:")||key.StartsWith("inode:")||key.StartsWith("disk-policy:")){
            var mount=key[(key.IndexOf(':')+1)..];var volume=LinuxPolicy.Volumes(r).FirstOrDefault(v=>v.Mount==mount);if(volume==null)return global::SysAdminAssistant.Core.ProductText.Get("Точка монтирования ")+mount+global::SysAdminAssistant.Core.ProductText.Get(" отсутствует в отчёте; данные не подменяются нулём.");
            if(volume.Error!="")return global::SysAdminAssistant.Core.ProductText.Get("Хост ")+r.MachineName+global::SysAdminAssistant.Core.ProductText.Get("; точка ")+mount+global::SysAdminAssistant.Core.ProductText.Get("; источник ")+volume.Source+global::SysAdminAssistant.Core.ProductText.Get("; ФС ")+volume.FileSystem+global::SysAdminAssistant.Core.ProductText.Get(". Ошибка: ")+volume.Error+global::SysAdminAssistant.Core.ProductText.Get(". Размер, остаток и inode не подтверждены. Проверьте findmnt, lsblk -f и доступность ФС; не форматируйте и не исправляй ФС без диагностики и резервной копии.");
            var rule=LinuxPolicy.EffectiveDisk(mount,p,volume.TotalBytes);var percent=volume.TotalBytes>0?100d*volume.AvailableBytes/volume.TotalBytes:0;
            var reasons=new List<string>();if(rule.FreePercent>0&&percent<=rule.FreePercent)reasons.Add(global::SysAdminAssistant.Core.ProductText.Get($"остаток {percent:0.0}% ≤ {rule.FreePercent}%"));if(rule.FreeMiB>0&&volume.AvailableBytes<=(long)rule.FreeMiB*1048576)reasons.Add(global::SysAdminAssistant.Core.ProductText.Get($"остаток ≤ {rule.FreeMiB} МиБ"));if(volume.Inodes is >0&&volume.FreeInodes is long free){if(rule.InodeFreePercent>0&&100d*free/volume.Inodes<=rule.InodeFreePercent)reasons.Add(global::SysAdminAssistant.Core.ProductText.Get($"свободные inode ≤ {rule.InodeFreePercent}%"));if(rule.InodeMinimum>0&&free<=rule.InodeMinimum)reasons.Add($"inode ≤ {rule.InodeMinimum}");}
            string Short(string value,int max)=>compact&&value.Length>max?value[..max]+"…":value;
            var text=global::SysAdminAssistant.Core.ProductText.Get($"Хост: {r.MachineName}; Проверено: {r.CapturedUtc.ToServerTime():dd.MM.yyyy HH:mm:ss}.\nТочка монтирования: {volume.Mount}; корень mount: {Short(volume.MountRoot,64)}; источник: {Short(volume.Source,120)}; ФС: {volume.FileSystem}; тип устройства: {volume.DeviceKind}; major:minor {volume.DeviceId}.\nВсего {AgentIssueAdvice.Size(volume.TotalBytes)}, занято {AgentIssueAdvice.Size(volume.UsedBytes)} ({(volume.TotalBytes>0?100d*volume.UsedBytes/volume.TotalBytes:0):0.0}%), доступно службе {AgentIssueAdvice.Size(volume.AvailableBytes)} ({percent:0.0}%). Зарезервировано ФС: {AgentIssueAdvice.Size(volume.ReservedBytes)}.\nInode: ")+(volume.Inodes is long total?global::SysAdminAssistant.Core.ProductText.Get($"свободно {volume.FreeInodes} из {total}"):global::SysAdminAssistant.Core.ProductText.Get("не переданы/не поддерживаются; нулевой остаток не предполагается"))+global::SysAdminAssistant.Core.ProductText.Get($".\nПорог этой точки: свободно ≤ {rule.FreePercent}% ИЛИ ≤ {rule.FreeMiB} МиБ; inode ≤ {rule.InodeFreePercent}% ИЛИ ≤ {rule.InodeMinimum}. Значение 0 выключает соответствующее условие.\nПричина: ")+(volume.Error!=""?volume.Error:key.StartsWith("disk-policy:")?global::SysAdminAssistant.Core.ProductText.Get("Абсолютный порог не меньше размера ФС; исправьте настройку точки монтирования"):string.Join("; ",reasons));
            text+=global::SysAdminAssistant.Core.ProductText.Get("\nДиагностика (на узле, только просмотр): df -hT; df -i; findmnt; lsblk -f. Это разные представления: раздел/том LVM не равен файловой системе, а одна ФС может иметь несколько точек монтирования; объёмы таких строк не складываются.");
            text+=mount is "/boot" or "/boot/efi"?global::SysAdminAssistant.Core.ProductText.Get("\nИсправление: сначала сверить uname -r и установленные пакеты ядер. Ненужные ядра удаляются штатным пакетным менеджером после проверки работающего и запасного ядра. Не удаляйте файлы вручную из /boot, EFI или загрузчика. Пороги /boot и /boot/efi отдельные и меняются в «Тома и пороги». Макет разделов/LVM эта программа не изменяет."):global::SysAdminAssistant.Core.ProductText.Get("\nИсправление: найдите источник роста файлов/inode; проверьте ротацию журналов и срок хранения бэкапов. Расширение ФС/LVM планируется после проверки резервной копии и схемы дисков. Не удаляйте базы или системные файлы наугад.");
            return text+global::SysAdminAssistant.Core.ProductText.Get("\nЗакрытие: свежий отчёт без сработавшего условия; inode и свободные байты восстанавливаются независимо.");
        }
        if(key.StartsWith("update-delivery:")&&r.Linux?.UpdateDelivery is {} d)return global::SysAdminAssistant.Core.ProductText.Get($"Хост {r.MachineName}. Ошибка доставки/проверки пакета отделена от systemd-службы.\nКод: {d.Code}; состояние: {d.State}; версия: {d.Version}; SHA256 пакета: {d.PackageHash}.\nПервое обнаружение {d.FirstUtc.ToServerTime():dd.MM.yyyy HH:mm:ss}; последнее {d.LastUtc.ToServerTime():dd.MM.yyyy HH:mm:ss}; повторов {d.Count}.\nПричина: {d.Message}\nЧто проверить: часы сервера/агента, публикацию полного пакета на сервере, место и права на узле. При ошибке подписи не отключайте проверку и не заменяй ключ издателя. Диагностика: journalctl -u sysadminassistant-agent-update.service -n 100 --no-pager; systemctl status sysadminassistant-agent-update.timer.\nЗакрытие: успешная проверенная установка либо свежий подписанный манифест, подтверждающий установленный файл. Успешный запуск oneshot без пакета ошибку доставки не закрывает.");
        if((key.StartsWith("service:")||key.StartsWith("systemd-job:")||key.StartsWith("systemd-schedule:"))&&r.Linux!=null){
            var rule=LinuxPolicy.EffectiveServices(p).FirstOrDefault(s=>key=="service:"+s.Name||key=="systemd-schedule:"+s.Name||key=="systemd-job:"+s.Name||r.Linux.Units.Any(u=>u.Name==s.Name&&key=="systemd-job:"+u.Trigger));
            var unit=r.Linux.Units.FirstOrDefault(u=>key=="systemd-job:"+u.Name)??r.Linux.Units.FirstOrDefault(u=>u.Name==rule?.Name);if(unit?.Type=="timer"&&key.StartsWith("systemd-job:"))unit=r.Linux.Units.FirstOrDefault(u=>u.Name==unit.Trigger)??unit;
            if(unit==null)return global::SysAdminAssistant.Core.ProductText.Get("Хост ")+r.MachineName+global::SysAdminAssistant.Core.ProductText.Get(". Состояние systemd unit отсутствует; проверьте точное имя, наличие unit и права чтения systemctl. Отсутствие данных не означает успешное выполнение.");
            if(unit.Type is not ("oneshot" or "timer"))return global::SysAdminAssistant.Core.ProductText.Get($"Хост {r.MachineName}; проверено: {r.CapturedUtc.ToServerTime():dd.MM.yyyy HH:mm:ss}.\nUnit {unit.Name}; Type={unit.Type}; состояние {unit.Active}/{unit.Sub}; Result={unit.Result}; ExecMainCode={unit.ExitCode}; ExecMainStatus={unit.ExitStatus}.\nСвязанный сокет: {(unit.Trigger.EndsWith(".socket",StringComparison.Ordinal)?unit.Trigger:global::SysAdminAssistant.Core.ProductText.Get("не передан агентом"))}.\nПричина: {finding.Title}\nЧто проверить: systemctl status и systemctl show для службы и связанного сокета; journalctl -u для журнала. Служба inactive/dead с успешным результатом и активным слушающим связанным сокетом считается исправной. Если сведений о сокете нет, обновите Linux-агент и дождитесь свежего отчёта.\nЗакрытие: свежий отчёт с работающей службой либо подтверждённым слушающим сокетом при нормальном завершении службы. Не перезапускайте SSH вслепую через единственное удалённое подключение.");
            return global::SysAdminAssistant.Core.ProductText.Get($"Хост {r.MachineName}; Проверено: {r.CapturedUtc.ToServerTime():dd.MM.yyyy HH:mm:ss}.\nUnit {unit.Name}; Type={unit.Type}; ActiveState={unit.Active}; SubState={unit.Sub}; Result={unit.Result}; ExecMainCode={unit.ExitCode}; ExecMainStatus={unit.ExitStatus}.\nПоследнее завершение/срабатывание: {unit.LastRunUtc?.ToServerTime():dd.MM.yyyy HH:mm:ss}; следующее (если передано): {unit.NextRunUtc?.ToServerTime():dd.MM.yyyy HH:mm:ss}; связанная служба {unit.Trigger}.\nОжидаемый интервал: ")+(rule?.MaxIntervalMinutes is int interval?interval+global::SysAdminAssistant.Core.ProductText.Get(" мин."):global::SysAdminAssistant.Core.ProductText.Get("не задан; просрочка по интервалу не предполагается"))+global::SysAdminAssistant.Core.ProductText.Get(".\nПричина: ")+finding.Title+global::SysAdminAssistant.Core.ProductText.Get("\nЧто проверить: systemctl status и systemctl show для указанного unit, journalctl -u для его журнала. Для oneshot успешный код 0 и inactive/dead после завершения — нормальное состояние. Начало следующего запуска и временное отсутствие данных не закрывают прежнюю ошибку; требуется подтверждённое новое успешное завершение. Для таймера отдельно проверяются активность таймера и результат связанного задания. Если интервал не задан и срок не передан systemd, программа не выдумывает расписание.\nЗакрытие: свежий успешный результат/состояние этого unit; ошибка пакета обновления контролируется отдельно. Не перезапускайте все службы и не удаляйте регистрацию агента ради снятия предупреждения.");
        }
        return null;
    }
}
